from pathlib import Path
p=Path('delivery-dashboard.html')
s=p.read_text(encoding='utf-8')

if 'https://cdn.tailwindcss.com' not in s:
    s=s.replace('<script src="https://unpkg.com/html5-qrcode@2.3.8/html5-qrcode.min.js"></script>', '<script src="https://unpkg.com/html5-qrcode@2.3.8/html5-qrcode.min.js"></script>\n<script src="https://cdn.tailwindcss.com"></script>\n<script>tailwind.config={theme:{extend:{colors:{meshgold:\'#f5c451\',meshnavy:\'#07111f\'}}}}</script>',1)

lux='''\n<style id="delivery-luxury-theme">\n:root{--lux-gold:#f5c451;--lux-gold2:#d99b27;--lux-navy:#050b14;--lux-slate:#0f1b2d;--lux-card:rgba(15,27,45,.80);--lux-line:rgba(245,196,81,.20);--lux-text:#f8fafc;--lux-muted:#cbd5e1;--lux-shadow:0 20px 60px rgba(0,0,0,.34)}\nhtml{background:#050b14;color-scheme:dark}body{background:radial-gradient(circle at 12% 0%,rgba(245,196,81,.10),transparent 24%),radial-gradient(circle at 88% 5%,rgba(37,99,235,.16),transparent 30%),linear-gradient(145deg,#030712 0%,#07111f 48%,#0b1424 100%)!important;color:var(--lux-text)!important;min-height:100vh}.app{max-width:1380px!important;padding:18px!important}\n.topbar{background:linear-gradient(135deg,rgba(15,27,45,.94),rgba(7,17,31,.86))!important;border:1px solid var(--lux-line)!important;border-radius:24px!important;padding:18px 20px!important;box-shadow:var(--lux-shadow),inset 0 1px 0 rgba(255,255,255,.04)!important;backdrop-filter:blur(20px)}.topbar h1{color:#fff!important;font-size:22px!important;font-weight:900!important}.topbar h1::first-letter{color:var(--lux-gold)}.muted{color:#cbd5e1!important}.btn{border-radius:13px!important;transition:transform .2s ease,box-shadow .2s ease,filter .2s ease}.btn:hover{transform:translateY(-2px);filter:brightness(1.06)}.btn-blue{background:linear-gradient(135deg,#2563eb,#1d4ed8)!important;box-shadow:0 8px 24px rgba(37,99,235,.25)}.btn-gray{background:rgba(71,85,105,.72)!important;border:1px solid rgba(148,163,184,.16)}.btn-red{box-shadow:0 8px 22px rgba(220,38,38,.18)}\n.finance{grid-template-columns:repeat(6,minmax(0,1fr))!important;gap:12px!important;margin:16px 0!important}.finance-card{position:relative;overflow:hidden;background:linear-gradient(145deg,rgba(15,27,45,.90),rgba(10,20,35,.76))!important;border:1px solid rgba(245,196,81,.19)!important;border-radius:22px!important;padding:16px!important;box-shadow:var(--lux-shadow),inset 0 1px 0 rgba(255,255,255,.03)!important;backdrop-filter:blur(18px);transition:.22s ease}.finance-card::after{content:"";position:absolute;width:92px;height:92px;left:-36px;top:-42px;border-radius:999px;background:radial-gradient(circle,rgba(245,196,81,.16),transparent 70%);pointer-events:none}.finance-card:hover{transform:translateY(-3px);border-color:rgba(245,196,81,.38)!important;box-shadow:0 22px 62px rgba(0,0,0,.40),0 0 22px rgba(245,196,81,.06)!important}.finance-card .label{color:#cbd5e1!important;font-size:12px!important;font-weight:800!important}.finance-card .value{color:#fff!important;font-size:23px!important;font-weight:950!important;text-shadow:0 0 18px rgba(245,196,81,.08)}.finance-card:nth-child(1) .value,.finance-card:nth-child(2) .value,.finance-card:nth-child(3) .value{color:#fde68a!important}.finance-card:nth-child(6) .value{color:#f5c451!important}\n.delivery-layout{grid-template-columns:240px minmax(0,1fr)!important;gap:16px!important}.tabs{background:rgba(7,17,31,.76)!important;border:1px solid rgba(148,163,184,.12)!important;border-radius:20px!important;padding:10px!important;backdrop-filter:blur(18px);box-shadow:var(--lux-shadow)}.tab{background:rgba(15,27,45,.72)!important;color:#cbd5e1!important;border:1px solid rgba(148,163,184,.12)!important;border-radius:13px!important;padding:12px!important;transition:.2s ease}.tab:hover{color:#fff!important;border-color:rgba(245,196,81,.30)!important;background:rgba(30,41,59,.88)!important}.tab.active{background:linear-gradient(135deg,#fde68a,#f5c451 55%,#d99b27)!important;color:#111827!important;border-color:#f5c451!important;box-shadow:0 10px 28px rgba(217,155,39,.24),0 0 20px rgba(245,196,81,.10)!important}.badge{background:rgba(148,163,184,.14)!important;color:#e2e8f0!important}.tab.active .badge{background:#111827!important;color:#fde68a!important}\n.toolbar{background:rgba(15,27,45,.82)!important;border:1px solid rgba(245,196,81,.16)!important;border-radius:18px!important;padding:12px!important;box-shadow:var(--lux-shadow)!important;backdrop-filter:blur(18px)}.toolbar input{background:rgba(2,8,23,.72)!important;color:#fff!important;border:1px solid rgba(148,163,184,.18)!important;border-radius:13px!important;padding:13px 14px!important;font-size:15px!important;outline:none!important;transition:.2s ease}.toolbar input::placeholder{color:#94a3b8}.toolbar input:focus{border-color:rgba(245,196,81,.55)!important;box-shadow:0 0 0 3px rgba(245,196,81,.09)!important}.toolbar .btn-blue{font-size:15px!important;padding:12px 16px!important}.toolbar button[data-clear-search]{background:rgba(100,116,139,.36)!important;border:1px solid rgba(148,163,184,.18)!important}\n.orders{gap:12px!important}.shipment{background:linear-gradient(145deg,rgba(15,27,45,.90),rgba(7,17,31,.82))!important;border:1px solid rgba(148,163,184,.12)!important;border-radius:20px!important;box-shadow:0 14px 40px rgba(0,0,0,.24)!important;transition:.22s ease;overflow:hidden}.shipment:hover{transform:translateY(-2px);border-color:rgba(245,196,81,.28)!important;box-shadow:0 18px 48px rgba(0,0,0,.31)!important}.shipment-summary{grid-template-columns:1.1fr 1.2fr 2fr 1fr auto!important;padding:15px!important;gap:12px!important}.shipment-details{border-top:1px solid rgba(148,163,184,.12)!important;padding:0 15px 15px!important}.code{color:#fde68a!important;font-size:17px!important}.chevron{color:#f5c451!important}.status{background:rgba(245,196,81,.11)!important;color:#fde68a!important;border:1px solid rgba(245,196,81,.20)!important}.secondary{color:#fbbf24!important}.grid{gap:10px!important}.item{background:rgba(2,8,23,.42)!important;border:1px solid rgba(148,163,184,.10)!important;border-radius:13px!important;padding:10px!important;color:#f8fafc!important}.item b{color:#cbd5e1!important}.money{color:#fde68a!important}.edit-box{border-top:1px dashed rgba(148,163,184,.20)!important}.edit-box select,.edit-box input,.edit-box textarea{background:rgba(2,8,23,.65)!important;color:#fff!important;border:1px solid rgba(148,163,184,.18)!important;border-radius:11px!important}.empty,.loading{background:rgba(15,27,45,.72)!important;border:1px dashed rgba(245,196,81,.20)!important;color:#cbd5e1!important;border-radius:18px!important}.pager button{background:rgba(15,27,45,.82)!important;color:#f8fafc!important;border:1px solid rgba(148,163,184,.14)!important;border-radius:11px!important}.pager button:not(:disabled):hover{border-color:rgba(245,196,81,.35)!important;color:#fde68a!important}\n.scanner-wrap{background:rgba(2,6,23,.94)!important;backdrop-filter:blur(10px)}.scanner-panel{background:linear-gradient(145deg,#0f1b2d,#07111f)!important;color:#fff!important;border:1px solid rgba(245,196,81,.24)!important;border-radius:22px!important;box-shadow:0 28px 80px rgba(0,0,0,.55)!important}.delivery-image-box{background:rgba(2,8,23,.42)!important;border:1px solid rgba(148,163,184,.12)!important}.delivery-image-preview{background:#07111f!important}.proof-status{color:#cbd5e1!important}.scan-result.show{background:rgba(22,163,74,.12)!important;border-color:rgba(74,222,128,.35)!important;color:#bbf7d0!important}.error{background:rgba(185,28,28,.14)!important;border-color:rgba(248,113,113,.28)!important;color:#fecaca!important}\n@media(max-width:1100px){.finance{grid-template-columns:repeat(3,minmax(0,1fr))!important}.delivery-layout{grid-template-columns:190px minmax(0,1fr)!important}}\n@media(max-width:760px){.app{padding:10px!important}.finance{grid-template-columns:repeat(2,minmax(0,1fr))!important}.delivery-layout{display:block!important}.tabs{position:static!important;display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr))!important;margin-bottom:12px}.tab{font-size:12px!important}.toolbar{display:grid!important;grid-template-columns:1fr auto!important}.toolbar input{grid-column:1/-1!important;min-width:0!important;width:100%!important}.toolbar .btn-blue{min-height:48px!important;font-size:15px!important}.toolbar .btn-gray{min-height:48px!important}.shipment-summary{grid-template-columns:1fr 1fr!important}.summary-address{grid-column:1/-1!important}}\n@media(max-width:520px){.finance{grid-template-columns:1fr 1fr!important;gap:8px!important}.finance-card{padding:12px!important}.finance-card .value{font-size:18px!important}.topbar{padding:14px!important}.topbar h1{font-size:18px!important}.tabs{grid-template-columns:1fr 1fr!important}.shipment-summary{grid-template-columns:1fr!important}.summary-address{grid-column:auto!important}.grid{grid-template-columns:1fr!important}.toolbar{grid-template-columns:1fr 1fr!important}.toolbar input{grid-column:1/-1!important}.toolbar button[data-clear-search]{position:absolute;left:22px;margin-top:7px}.toolbar .btn-blue,.toolbar .btn-gray{width:100%!important}.btn{min-height:44px}.scanner-panel{width:100%!important}}\n</style>\n'''
if 'id="delivery-luxury-theme"' not in s:
    s=s.replace('</style>\n</head>', '</style>\n'+lux+'</head>',1)

p.write_text(s,encoding='utf-8')
print('delivery luxury UI patch applied')
